def parse_env(text: str) -> dict:
    result = {}
    if not text:
        return result
    lines = text.split('\n')
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue
        if '=' not in stripped:
            continue
        key, val = stripped.split('=', 1)
        key = key.strip()
        val = val.strip()
        if len(val) >= 2:
            if (val[0] == '"' and val[-1] == '"') or (val[0] == "'" and val[-1] == "'"):
                val = val[1:-1]
        result[key] = val
    return result
```

